foreach ( $pilots as $product_id => $fields ) {
    $post = get_post( $product_id );
    if ( ! $post ) { WP_CLI::warning( "[{$product_id}] introuvable — ignoré." ); continue; }
    if ( ! get_post_meta( $product_id, '_clo_desc_backup', true ) ) {
        update_post_meta( $product_id, '_clo_desc_backup', $post->post_content );
    }
    foreach ( $fields as $key => $val ) { update_post_meta( $product_id, $key, $val ); }
    WP_CLI::success( "[{$product_id}] {$post->post_title} — " . count( $fields ) . " champs écrits." );
}
WP_CLI::success( "Import terminé — " . count( $pilots ) . " produits traités." );
WP_CLI::log( "Assignez les images via la meta box admin > Description CLO pour chaque produit." );
